9: @interface RSRootListController : PSListController <UIImagePickerControllerDelegate, UINavigationControllerDelegate, UIDocumentPickerDelegate>
10: @end
11: 
12: @implementation RSRootListController
13: - (NSArray *)specifiers {
14:     if (!_specifiers) _specifiers = [[self loadSpecifiersFromPlistName:@"Root" target:self] retain];
15:     return _specifiers;
16: }
17: - (void)rsAlert:(NSString *)title message:(NSString *)message {
18:     UIAlertController *a = [UIAlertController alertControllerWithTitle:title message:message preferredStyle:UIAlertControllerStyleAlert];
19:     [a addAction:[UIAlertAction actionWithTitle:@"确定" style:UIAlertActionStyleDefault handler:nil]];
20:     [self presentViewController:a animated:YES completion:nil];
21: }
22: - (void)rsPickPhoto {
23:     if (![UIImagePickerController isSourceTypeAvailable:UIImagePickerControllerSourceTypePhotoLibrary]) {
24:         [self rsAlert:@"无法打开相册" message:@"当前系统不支持相册选择器。"]; return;
25:     }
26:     UIImagePickerController *p = [[UIImagePickerController alloc] init];
27:     p.sourceType = UIImagePickerControllerSourceTypePhotoLibrary;
28:     p.delegate = self;
29:     p.allowsEditing = NO;
30:     [self presentViewController:p animated:YES completion:nil];
31:     [p release];
32: }
33: - (void)rsPickFile {
34:     UIDocumentPickerViewController *p = [[UIDocumentPickerViewController alloc] initWithDocumentTypes:@[@"public.png", @"public.jpeg", @"public.image"] inMode:UIDocumentPickerModeImport];
35:     p.delegate = self;
36:     [self presentViewController:p animated:YES completion:nil];
37:     [p release];
38: }
39: - (NSString *)rsCustomPath {
40:     return @"/var/mobile/Library/Application Support/RecordingSharingan/eye/custom.png";
41: }
42: - (void)rsNotifyAndSelect:(BOOL)selectCustom {
43:     if (selectCustom) {
44:         CFPreferencesSetAppValue(CFSTR("eyeStyle"), (CFPropertyListRef)[NSNumber numberWithInt:6], CFSTR("com.tu.recordingsharingan.settings"));
45:         CFPreferencesAppSynchronize(CFSTR("com.tu.recordingsharingan.settings"));
46:     }
47:     notify_post("com.tu.recordingsharingan.settings.changed");
48:     [self reloadSpecifiers];
49: }
50: - (void)rsImportImage:(UIImage *)image {
51:     if (!image || image.size.width <= 0 || image.size.height <= 0) {
52:         [self rsAlert:@"导入失败" message:@"无法解码图片，请选择 PNG 或 JPG。"]; return;
53:     }
54:     const CGSize size = CGSizeMake(512,512);
55:     UIGraphicsBeginImageContextWithOptions(size, NO, 1.0);
56:     CGRect rect = CGRectZero;
57:     CGFloat ratio = MIN(size.width/image.size.width, size.height/image.size.height);
58:     rect.size = CGSizeMake(image.size.width*ratio, image.size.height*ratio);
59:     rect.origin = CGPointMake((512-rect.size.width)/2.0, (512-rect.size.height)/2.0);
60:     [image drawInRect:rect];
61:     UIImage *scaled = UIGraphicsGetImageFromCurrentImageContext();
62:     UIGraphicsEndImageContext();
63:     NSData *png = UIImagePNGRepresentation(scaled);
64:     NSString *path = [self rsCustomPath];
65:     NSString *dir = [path stringByDeletingLastPathComponent];
66:     NSError *error = nil;
67:     if (![[NSFileManager defaultManager] createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:&error] ||
68:         !png || ![png writeToFile:path options:NSDataWritingAtomic error:&error]) {
69:         [self rsAlert:@"保存失败" message:error.localizedDescription ?: @"无法写入素材文件"]; return;
70:     }
71:     [self rsNotifyAndSelect:YES];
72:     [self rsAlert:@"导入成功" message:@"已生成 512×512 透明 PNG 并选择「自定义 PNG」。素材会随插件设置通知刷新。"];
73: }
74: - (void)rsRemoveCustom {
75:     NSError *err = nil;
76:     NSString *path = [self rsCustomPath];
77:     if ([[NSFileManager defaultManager] fileExistsAtPath:path] &&
78:         ![[NSFileManager defaultManager] removeItemAtPath:path error:&err]) {
79:         [self rsAlert:@"删除失败" message:err.localizedDescription]; return;
80:     }
